    public static function table(){return CAFCC_Bank_DB::table('reviews');}
    public static function get($id,$lock=false){global $wpdb;$t=self::table();$row=$wpdb->get_row($wpdb->prepare("SELECT * FROM $t WHERE id=%d".($lock?' FOR UPDATE':''),$id),ARRAY_A);if($row){$row['data']=json_decode($row['payload'],true);$row['approval_state']=json_decode($row['approvals'],true);unset($row['payload'],$row['approvals']);}return $row;}
