        $allowed=array('stable_id','source_hash','source_key','subject_code','source_type','exam_attempt','mtp_series','section','reference','subreference','title','official_url','scheme','edition_id','law_context','question_page','question_coordinates','heading_evidence','classification','reasoning','confidence','exceptions','answer','review_notes','rights_mode','rights_basis','review_question_text','review_answer_text','extraction_status','source_revision','engine_revision','previous_corrections','marks','marks_verified','question_type');
