        $data['edition_id']=CAFCC_Repository::id($data['edition_id']??null,true);if(is_wp_error($data['edition_id']))return $data['edition_id'];
        $classification=$data['classification']??array();if(!is_array($classification)||!array_is_list($classification)||count($classification)>30)return CAFCC_Repository::error('Classification must be up to 30 node IDs.');$ids=array();
        foreach($classification as $id){$id=CAFCC_Repository::id($id);if(is_wp_error($id))return $id;$n=CAFCC_Academic::get('taxonomy',$id);if(!$n||'module'===$n['node_type'])return CAFCC_Repository::error('Select an existing chapter/unit/topic/subtopic.');if($data['edition_id']&&(int)$n['edition_id']!==$data['edition_id']&&'IBS'!==$data['subject_code'])return CAFCC_Repository::error('Historical/subject taxonomy mismatch; no automatic remapping.');$ids[]=$id;}$data['classification']=array_values(array_unique($ids));
        if($data['edition_id']){$ed=CAFCC_Academic::get('editions',$data['edition_id']);$sub=$ed?CAFCC_Repository::get('subjects',$ed['subject_id']):null;if(!$sub||$sub['code']!==$data['subject_code'])return CAFCC_Repository::error('Edition must belong to the primary subject.');}
