        if(!empty($answer['official_url'])){$url=CAFCC_Repository::official_url($answer['official_url']);if(is_wp_error($url))return $url;$answer['official_url']=$url;}
        if(!empty($answer['question_identity'])&&$answer['question_identity']!==$data['stable_id'])return CAFCC_Repository::error('Answer belongs to another question identity.');
