        $marks=$data['marks']??null;if(null!==$marks&&''!==$marks&&(!is_numeric($marks)||$marks<0||$marks>1000||true!==($data['marks_verified']??false)))return CAFCC_Repository::error('Leave marks blank unless source-verified.');$data['marks']=(''===$marks?null:$marks);$data['marks_verified']=null!==$data['marks']&&true===($data['marks_verified']??false);
        return $data;
    }
    private static function columns($data){return array('stable_id'=>$data['stable_id'],'source_hash'=>$data['source_hash'],'source_key'=>$data['source_key'],'subject_code'=>$data['subject_code'],'source_type'=>$data['source_type'],'exam_attempt'=>$data['exam_attempt'],'mtp_series'=>$data['mtp_series'],'section_label'=>$data['section'],'question_number'=>$data['reference'],'subquestion_number'=>$data['subreference'],'payload'=>wp_json_encode($data),'payload_hash'=>hash('sha256',wp_json_encode($data)),'modified_at'=>current_time('mysql',true));}
    public static function import_preview($input){
        if(is_wp_error($e=self::admin()))return $e;$rows=$input['records']??null;$key=$input['batch_key']??'';
        if(!is_string($key)||!preg_match('/^[A-Za-z0-9_.:-]{2,120}$/D',$key)||!is_array($rows)||!array_is_list($rows)||!count($rows)||count($rows)>100)return CAFCC_Repository::error('Use a named batch of 1–100 records.');
        $clean=array();$errors=array();$seen=array();global $wpdb;$t=self::table();
        foreach($rows as $i=>$r){$v=self::clean($r);if(is_wp_error($v)){$errors[]=array('row'=>$i+1,'message'=>$v->get_error_message());continue;}if(isset($seen[$v['stable_id']])){$errors[]=array('row'=>$i+1,'message'=>'Duplicate stable identity in batch.');continue;}$seen[$v['stable_id']]=true;$old=$wpdb->get_row($wpdb->prepare("SELECT id,payload_hash FROM $t WHERE stable_id=%s",$v['stable_id']),ARRAY_A);$hash=hash('sha256',wp_json_encode($v));$clean[]=array('data'=>$v,'existing_id'=>$old['id']??null,'duplicate'=>$old&&$old['payload_hash']===$hash,'conflict'=>$old&&$old['payload_hash']!==$hash);}
        $token=wp_generate_uuid4();set_transient('cafcc_bank_preview_'.$token,array('owner'=>get_current_user_id(),'batch_key'=>$key,'rows'=>$clean,'expires'=>time()+1800,'can_apply'=>!$errors&&!count(array_filter($clean,function($r){return $r['conflict'];}))),1800);
        return array('token'=>$token,'records'=>count($clean),'errors'=>$errors,'duplicates'=>count(array_filter($clean,function($r){return $r['duplicate'];})),'conflicts'=>count(array_filter($clean,function($r){return $r['conflict'];})),'can_apply'=>!$errors&&!count(array_filter($clean,function($r){return $r['conflict'];})));
    }
    public static function import_apply($token){
        if(is_wp_error($e=self::admin()))return $e;if(!is_string($token)||!preg_match('/^[a-f0-9-]{36}$/D',$token))return CAFCC_Repository::error('Invalid preview token.');$preview=get_transient('cafcc_bank_preview_'.$token);if(!$preview||empty($preview['can_apply'])||$preview['owner']!==get_current_user_id()||$preview['expires']<time())return CAFCC_Repository::error('Preview expired or belongs to another administrator.',409);
        return CAFCC_Academic::transaction(function()use($preview,$token){global $wpdb;$t=self::table();$added=0;$skipped=0;
            foreach($preview['rows'] as $r){$v=$r['data'];$row=self::columns($v);$old=$wpdb->get_row($wpdb->prepare("SELECT * FROM $t WHERE stable_id=%s FOR UPDATE",$v['stable_id']),ARRAY_A);
                if($old){if($old['payload_hash']!==$row['payload_hash'])return CAFCC_Repository::error('Existing correction differs. Reprocessing cannot overwrite it; review conflict.',409);$skipped++;continue;}
                $row=array_merge($row,array('revision'=>1,'status'=>'needs_review','publication_status'=>'draft','approvals'=>'{}','batch_key'=>$preview['batch_key']));if(false===$wpdb->insert($t,$row))return CAFCC_Repository::error('Cannot import draft candidate.',409);$id=$wpdb->insert_id;if(!self::audit(self::get($id),'import_draft'))return CAFCC_Repository::error('Cannot retain audit.',500);$added++;
            }
            $bt=CAFCC_Bank_DB::table('batches');$wpdb->query($wpdb->prepare("INSERT IGNORE INTO $bt (batch_key,owner_id,batch_type,status,manifest,created_at) VALUES(%s,%d,'research','drafts_imported',%s,%s)",$preview['batch_key'],get_current_user_id(),wp_json_encode(array('rows'=>count($preview['rows']))),current_time('mysql',true)));
            delete_transient('cafcc_bank_preview_'.$token);return array('added'=>$added,'skipped_identical'=>$skipped,'publication_status'=>'draft');
        });
    }
    public static function save($id,$input){
        if(is_wp_error($e=self::admin()))return $e;if(!is_array($input)||array_diff(array_keys($input),array('expected_revision','data')))return CAFCC_Repository::error('Unexpected review edit.');
        return CAFCC_Academic::transaction(function()use($id,$input){global $wpdb;$old=self::get($id,true);if(!$old)return CAFCC_Repository::error('Review not found.',404);if((string)($input['expected_revision']??'')!==(string)$old['revision'])return CAFCC_Repository::error('Stale review revision. Reload before editing.',409);
            $data=self::clean($input['data']??array());if(is_wp_error($data))return $data;
            foreach(array('stable_id','source_hash','source_key','subject_code','source_type','exam_attempt','mtp_series','section','reference','subreference') as $k){if((string)$data[$k] !== (string)$old['data'][$k])return CAFCC_Repository::error('Source/question identity is immutable. Hold this record and import a corrected source revision.',409);}
            $approvals=$old['approval_state'];$changed=array();foreach(self::STAGES as $stage){if(self::fingerprint($old,$stage)!==self::fingerprint(array_merge($old,array('data'=>$data)),$stage))$changed[]=$stage;}
            if(in_array('source',$changed,true))$changed=self::STAGES;
            if(in_array('boundary',$changed,true))$changed=array_unique(array_merge($changed,array('classification','answer_mapping','question_revision','answer_revision')));
            if(in_array('answer_mapping',$changed,true))$changed[]='answer_revision';
            if(in_array('rights',$changed,true))$changed=array_merge($changed,array('question_revision','answer_revision'));
            foreach($changed as $stage)unset($approvals[$stage]);unset($approvals['publication']);
            $row=array_merge(self::columns($data),array('revision'=>(int)$old['revision']+1,'approvals'=>wp_json_encode($approvals),'status'=>'needs_review','publication_status'=>'draft'));
            if(false===$wpdb->update(self::table(),$row,array('id'=>$id))||!self::audit(self::get($id),'saved_draft'))return CAFCC_Repository::error('Cannot retain review revision.',500);return self::get($id);
        });
    }
    private static function content_version($row,$kind){global $wpdb;if(empty($row['question_id']))return array('reference_only');$t=CAFCC_Practice::table('content');$r=$wpdb->get_row($wpdb->prepare("SELECT id,revision,approved_revision,rights_type,rights_basis,rights_expires,review_status,publication_status FROM $t WHERE question_id=%d AND content_kind=%s",$row['question_id'],$kind),ARRAY_A);return $r?:array('reference_only');}
    public static function fingerprint($row,$stage){
        $d=$row['data'];$sets=array('source'=>array('source_hash','source_key','subject_code','source_type','exam_attempt','mtp_series','official_url','scheme','edition_id','law_context','source_revision'),'boundary'=>array('section','reference','subreference','question_page','question_coordinates','heading_evidence','marks','marks_verified'),'classification'=>array('edition_id','classification','reasoning'),'answer_mapping'=>array('answer'),'rights'=>array('rights_mode','rights_basis'));
        $v=in_array($stage,array('question_revision','answer_revision'),true)?self::content_version($row,'question_revision'===$stage?'question':'answer'):array_intersect_key($d,array_flip($sets[$stage]??array()));return hash('sha256',wp_json_encode($v));
