    private static function stage_valid($row,$stage){
        $d=$row['data'];
        if('source'===$stage&&(!$d['official_url']||!$d['scheme']||!$d['edition_id']||in_array($d['subject_code'],array('DT','IDT'),true)&&!$d['law_context']))return 'Verify official source, scheme, historical edition and tax applicability.';
        if('boundary'===$stage&&(!$d['question_page']||!$d['question_coordinates']))return 'Inspect and record the source page and exact question boundary.';
        if('classification'===$stage){if(!$d['edition_id']||!$d['classification']||!$d['reasoning'])return 'Choose edition-specific nodes and record classification reasoning.';$haschapter=false;foreach($d['classification'] as $id){$n=CAFCC_Academic::get('taxonomy',$id);if(!CAFCC_Academic::path_published($id))return 'Review/publish the taxonomy path in the academic manager first.';if('chapter'===$n['node_type']||array_filter(self::ancestors($id),function($n){return $n['node_type']==='chapter';}))$haschapter=true;}if(!$haschapter)return 'A chapter relationship is required.';}
        if('answer_mapping'===$stage){$a=$d['answer'];if(empty($a['question_identity'])||$a['question_identity']!==$d['stable_id']||($a['question_reference']??null)!==$d['reference']||($a['question_subreference']??'')!==$d['subreference']||empty($a['page'])||empty($a['official_url'])||!preg_match('/^[a-f0-9]{64}$/D',$a['source_hash']??''))return 'Verify one exact question/subpart answer source, hash, reference and page. Do not infer from working-note numbers.';foreach($a['answer_ids']??array() as $aid){$answer=CAFCC_Academic::get('answers',$aid);if(!$answer||empty($row['question_id'])||(int)$answer['question_id']!==(int)$row['question_id']||!CAFCC_Academic::row_published($answer)||($answer['occurrence_id']&&(int)$answer['occurrence_id']!==(int)$row['occurrence_id']))return 'Explicit answer ID belongs to another question/occurrence or is unpublished.';}}
        if('rights'===$stage&&(!in_array($d['rights_mode'],array('reference_only','original','licensed_private_review','licensed_public'),true)||!$d['rights_basis']))return 'Record rights evidence, or explicitly approve reference-only student publication.';
        if(in_array($stage,array('question_revision','answer_revision'),true)){$v=self::content_version($row,'question_revision'===$stage?'question':'answer');if(isset($v['revision'])&&((string)$v['approved_revision']!==(string)$v['revision']||$v['review_status']!=='verified'||$v['publication_status']!=='published'))return 'Review and separately approve the current permitted-content revision in Practice content & rights first.';}
        return '';
    }
    private static function ancestors($id){$node=CAFCC_Academic::get('taxonomy',$id);return array_map(function($nid){return CAFCC_Academic::get('taxonomy',$nid);},CAFCC_Explorer::ancestors($node));}
    public static function decision($id,$input){
        if(is_wp_error($e=self::admin()))return $e;if(!is_array($input)||array_diff(array_keys($input),array('expected_revision','action','confirmed')))return CAFCC_Repository::error('Unexpected approval fields.');
        return CAFCC_Academic::transaction(function()use($id,$input){global $wpdb;$row=self::get($id,true);if(!$row)return CAFCC_Repository::error('Review not found.',404);if((string)($input['expected_revision']??'')!==(string)$row['revision'])return CAFCC_Repository::error('Stale review decision. Reload the latest revision.',409);if(true!==($input['confirmed']??false))return CAFCC_Repository::error('Explicit review confirmation is required.');
            $action=$input['action']??'';$a=$row['approval_state'];$pub='draft';$status='needs_review';
            if(in_array($action,self::STAGES,true)){$error=self::stage_valid($row,$action);if($error)return CAFCC_Repository::error($error);$a[$action]=array('fingerprint'=>self::fingerprint($row,$action),'reviewer'=>get_current_user_id(),'timestamp'=>current_time('mysql',true),'reviewed_revision'=>(int)$row['revision']);unset($a['publication']);}
            elseif('publish'===$action){foreach(self::STAGES as $stage){if(empty($a[$stage])||$a[$stage]['fingerprint']!==self::fingerprint($row,$stage)||self::stage_valid($row,$stage))return CAFCC_Repository::error('Publication blocked: review the current '.$stage.' stage.',409);}
                self::$writing=true;try{$mapped=self::materialize($row);}finally{self::$writing=false;}if(is_wp_error($mapped))return $mapped;$row=array_merge($row,$mapped);$pub='published';$status='approved';$a['publication']=array('reviewer'=>get_current_user_id(),'timestamp'=>current_time('mysql',true),'reviewed_revision'=>(int)$row['revision']);
            }elseif(in_array($action,array('hold','reject'),true)){$status='hold'===$action?'hold':'rejected';unset($a['publication']);}else return CAFCC_Repository::error('Unknown review action.');
            $values=array('revision'=>(int)$row['revision']+1,'approvals'=>wp_json_encode($a),'status'=>$status,'publication_status'=>$pub,'modified_at'=>current_time('mysql',true));foreach(array('question_id','occurrence_id') as $k)if(!empty($row[$k]))$values[$k]=$row[$k];
            if(false===$wpdb->update(self::table(),$values,array('id'=>$id))||!self::audit(self::get($id),'decision_'.$action))return CAFCC_Repository::error('Cannot save audited approval.',500);return self::get($id);
        });
    }
    private static function materialize($row){
