        $doc=$existing_occ?CAFCC_Academic::get('documents',$existing_occ['document_id']):CAFCC_Academic::by_key('documents',$sourcekey);
        if($doc && ($doc['official_url']!==$d['official_url'] || (int)$doc['edition_id']!==(int)$d['edition_id']))return CAFCC_Repository::error('Existing source identity/edition differs; hold instead of remapping IDs.',409);
        if(!$doc)$doc=CAFCC_Academic::save('documents',array_merge(array('document_key'=>$sourcekey,'edition_id'=>$d['edition_id'],'title'=>$d['title']?:$d['source_key'],'source_type'=>$d['source_type'],'exam_attempt'=>$d['exam_attempt'],'mtp_series'=>$d['mtp_series'],'official_url'=>$d['official_url'],'issue_period'=>''),$pub),0,null,true);
        if(is_wp_error($doc))return $doc;$doc=CAFCC_Academic::save('documents',$pub,(int)$doc['id'],null,true);if(is_wp_error($doc))return $doc;$chapter=null;foreach($d['classification'] as $nid){foreach(self::ancestors($nid) as $n){if('chapter'===$n['node_type']&&(int)$n['edition_id']===(int)$d['edition_id']){$chapter=$n['id'];break 2;}}}if(!$chapter)return CAFCC_Repository::error('Choose a primary-edition chapter before publication.');
        $ed=CAFCC_Academic::get('editions',$d['edition_id']);$qkey='B-'.substr(hash('sha256',$d['stable_id']),0,48);$q=!empty($row['question_id'])?CAFCC_Academic::get('questions',$row['question_id']):CAFCC_Academic::by_key('questions',$qkey);
        if(!$q)$q=CAFCC_Academic::save('questions',array_merge(array('stable_key'=>$qkey,'edition_id'=>$d['edition_id'],'primary_subject_id'=>$ed['subject_id'],'document_id'=>$doc['id'],'chapter_node_id'=>$chapter,'title'=>$d['subject_code'].' · '.$d['source_type'].' · '.$d['exam_attempt'].' · Q'.$d['reference'].($d['subreference']?'('.$d['subreference'].')':''),'question_number'=>$d['reference'],'question_type'=>$d['question_type']?:'unknown'),$pub),0,null,true);
        elseif(!empty($row['question_id'])&&(int)$row['question_id']!==(int)$q['id'])return CAFCC_Repository::error('Question identity conflict.',409);
        if(is_wp_error($q))return $q;
