        global $wpdb;$tags=CAFCC_DB::table('question_tags');$wpdb->update($tags,array('publication_status'=>'draft'),array('question_id'=>$q['id']));
        foreach($d['classification'] as $nid){$old=$wpdb->get_var($wpdb->prepare("SELECT id FROM $tags WHERE question_id=%d AND node_id=%d",$q['id'],$nid));$r=CAFCC_Academic::save('tags',array_merge(array('question_id'=>$q['id'],'node_id'=>$nid),$pub),(int)$old,null,true);if(is_wp_error($r))return $r;}
        $occ=$existing_occ?:CAFCC_Academic::by_key('occurrences','O-'.$qkey);if(!$occ)$occ=CAFCC_Academic::save('occurrences',array_merge(array('occurrence_key'=>'O-'.$qkey,'question_id'=>$q['id'],'document_id'=>$doc['id'],'edition_id'=>$d['edition_id'],'question_number'=>$d['reference'],'subquestion_number'=>$d['subreference'],'page_reference'=>$d['question_page'],'question_type'=>$d['question_type']?:'unknown','marks'=>$d['marks'],'marks_verified'=>(int)$d['marks_verified']),$pub),0,null,true);
        if(is_wp_error($occ))return $occ;
        foreach(array('documents'=>$doc,'questions'=>$q,'occurrences'=>$occ) as $kind=>$record){$v=CAFCC_Academic::save($kind,$pub,(int)$record['id'],null,true);if(is_wp_error($v))return $v;}
        $answer=$d['answer'];$ak='A-'.$qkey;$old=CAFCC_Academic::by_key('answers',$ak);$r=CAFCC_Academic::save('answers',array_merge(array('answer_key'=>$ak,'question_id'=>$q['id'],'occurrence_id'=>$occ['id'],'answer_mode'=>'official_link','answer_text'=>'','official_url'=>$answer['official_url'],'source_location'=>'Page '.$answer['page'].' · Q'.$answer['reference'].(!empty($answer['subreference'])?'('.$answer['subreference'].')':'')),$pub),$old?(int)$old['id']:0,null,true);if(is_wp_error($r))return $r;
        return array('question_id'=>(int)$q['id'],'occurrence_id'=>(int)$occ['id']);
    }
    public static function occurrence_guard($alias){$t=self::table();return " AND EXISTS(SELECT 1 FROM $t br WHERE br.occurrence_id=$alias.id AND br.publication_status='published' AND br.status='approved')";}
    public static function question_guard(){ $t=self::table();return " AND EXISTS(SELECT 1 FROM $t bq WHERE bq.question_id=q.id AND bq.publication_status='published' AND bq.status='approved')"; }
    public static function invalidate($kind,$id){
        if(self::$writing)return;global $wpdb;$t=self::table();$where='1=1';$args=array();
        if(in_array($kind,array('questions','tags','answers','occurrences','subject_tags'),true)){$r=CAFCC_Academic::get($kind,$id);$qid='questions'===$kind?$id:($r['question_id']??0);$where='question_id=%d';$args[]=$qid;}
        elseif('documents'===$kind){$q=CAFCC_DB::table('questions');$where="question_id IN (SELECT id FROM $q WHERE document_id=%d)";$args[]=$id;}
        elseif('taxonomy'===$kind){$tags=CAFCC_DB::table('question_tags');$cl=CAFCC_Bank_DB::table('closure');$where="question_id IN(SELECT it.question_id FROM $tags it JOIN $cl ic ON ic.descendant_id=it.node_id WHERE ic.ancestor_id=%d) OR EXISTS(SELECT 1 FROM $cl jc WHERE jc.ancestor_id=%d AND JSON_CONTAINS($t.payload,CAST(jc.descendant_id AS CHAR),'$.classification'))";$args=array($id,$id);}
        elseif('editions'===$kind){$where="JSON_UNQUOTE(JSON_EXTRACT(payload,'$.edition_id'))=%s";$args[]=(string)$id;}
        else return;
        $rows=$wpdb->get_results($args?$wpdb->prepare("SELECT id FROM $t WHERE $where",$args):"SELECT id FROM $t WHERE $where",ARRAY_A);
        foreach($rows as $r){$row=self::get($r['id']);if(!$row)continue;$a=$row['approval_state'];unset($a['classification'],$a['publication']);$wpdb->update($t,array('publication_status'=>'draft','status'=>'needs_review','revision'=>(int)$row['revision']+1,'approvals'=>wp_json_encode($a),'modified_at'=>current_time('mysql',true)),array('id'=>$r['id']));self::audit(self::get($r['id']),'master_changed');}
    }
    public static function answers($qid,$occid=0){
        if(!CAFCC_Practice::visible_question($qid))return CAFCC_Repository::error('Published question not found.',404);global $wpdb;$t=self::table();
        $rows=$wpdb->get_results($wpdb->prepare("SELECT * FROM $t WHERE question_id=%d AND publication_status='published' AND status='approved'",$qid),ARRAY_A);
        if(!$occid&&count($rows)!==1)return CAFCC_Repository::error('Select the exact source occurrence.',409);
        $row=null;foreach($rows as $r)if(!$occid||(int)$r['occurrence_id']===$occid)$row=$r;if(!$row)return CAFCC_Repository::error('Answer occurrence not found.',404);
        $row=self::get($row['id']);if(empty($row['approval_state']['answer_mapping'])||$row['approval_state']['answer_mapping']['fingerprint']!==self::fingerprint($row,'answer_mapping'))return CAFCC_Repository::error('Answer mapping requires review.',404);
        $a=$row['data']['answer'];$items=array();$permitted=CAFCC_Practice::public_content($qid,'answer');if($permitted)$items[]=array_merge(array('mode'=>'permitted_html'),$permitted);foreach($a['answer_ids']??array() as $aid){$ar=CAFCC_Academic::get('answers',$aid);if(!$ar||(int)$ar['question_id']!==$qid||!CAFCC_Academic::row_published($ar)||($ar['occurrence_id']&&(int)$ar['occurrence_id']!==(int)$row['occurrence_id']))continue;if('official_link'===$ar['answer_mode'])$items[]=array('mode'=>'official_link','official_url'=>$ar['official_url'],'source_location'=>$ar['source_location']);elseif($ar['rights_basis']&&$ar['answer_text'])$items[]=array('mode'=>$ar['answer_mode'],'answer_text'=>$ar['answer_text'],'rights_label'=>'authored'===$ar['answer_mode']?'Independently authored solution':'Licensed solution');}
        if(!array_key_exists('answer_ids',$a))$items[]=array('mode'=>'official_link','official_url'=>$a['official_url'],'source_location'=>'Page '.$a['page'].' · Q'.$a['reference'].(!empty($a['subreference'])?'('.$a['subreference'].')':''));return array('items'=>$items,'empty_message'=>'No reviewed solution is available.');
    }
    public static function content_allowed($qid,$kind){
        global $wpdb;$t=self::table();$ids=$wpdb->get_col($wpdb->prepare("SELECT id FROM $t WHERE question_id=%d AND publication_status='published' AND status='approved'",$qid));
        foreach($ids as $id){$r=self::get($id);$stage='question'===$kind?'question_revision':'answer_revision';if(in_array($r['data']['rights_mode'],array('original','licensed_public'),true)&&!empty($r['approval_state'][$stage])&&$r['approval_state'][$stage]['fingerprint']===self::fingerprint($r,$stage))return true;}return false;
    }
    public static function listing($r){
        global $wpdb;$page=$r->get_param('page')??1;$search=$r->get_param('search')??'';$status=$r->get_param('status')??'';$sort=$r->get_param('sort')??'id';$direction=$r->get_param('direction')??'DESC';$subject=$r->get_param('subject')??'';
        if(!is_scalar($page)||!preg_match('/^[1-9][0-9]{0,4}$/D',(string)$page)||!is_string($search)||strlen($search)>120||!in_array($sort,array('id','subject_code','source_type','exam_attempt','status','modified_at'),true)||!in_array($direction,array('ASC','DESC'),true)||!is_string($status)||!is_string($subject))return CAFCC_Repository::error('Invalid table filter.');
        $where='1=1';$args=array();$after=$r->get_param('after_id');if($after){$after=CAFCC_Repository::id($after);if(is_wp_error($after))return $after;$where.=' AND id>%d';$args[]=$after;}foreach(array('status'=>$status,'subject_code'=>$subject) as $k=>$v){if($v){$where.=" AND $k=%s";$args[]=$v;}}if($search){$where.=' AND (stable_id LIKE %s OR question_number LIKE %s OR exam_attempt LIKE %s OR payload LIKE %s)';$like='%'.$wpdb->esc_like($search).'%';array_push($args,$like,$like,$like,$like);}
        $t=self::table();$count=(int)$wpdb->get_var($args?$wpdb->prepare("SELECT COUNT(*) FROM $t WHERE $where",$args):"SELECT COUNT(*) FROM $t WHERE $where");$sql="SELECT id FROM $t WHERE $where ORDER BY $sort $direction LIMIT 50 OFFSET %d";$args[]=((int)$page-1)*50;$ids=$wpdb->get_col($wpdb->prepare($sql,$args));return array('items'=>array_map(function($id){$r=self::get($id);$r['has_private_preview']=!empty($r['data']['review_question_text'])||!empty($r['data']['review_answer_text']);unset($r['data']['review_question_text'],$r['data']['review_answer_text'],$r['data']['previous_corrections']);return $r;},$ids),'total'=>$count,'per_page'=>50,'page'=>(int)$page);
    }
    public static function body($r,$limit=2000000){if(strlen($r->get_body())>$limit)return CAFCC_Repository::error('Use a batch smaller than 2 MB.',413);$v=$r->get_json_params();return is_array($v)&&!array_is_list($v)?$v:CAFCC_Repository::error('Send a JSON object.');}
    public static function adopt($occid,$input){
        if(is_wp_error($e=self::admin()))return $e;$occ=CAFCC_Academic::get('occurrences',$occid);if(!$occ)return CAFCC_Repository::error('Choose an existing connected occurrence. Legacy references must first be connected through the retained academic manager.');
        global $wpdb;$t=self::table();if($wpdb->get_var($wpdb->prepare("SELECT id FROM $t WHERE occurrence_id=%d",$occid)))return CAFCC_Repository::error('Occurrence is already in review.',409);
        $q=CAFCC_Academic::get('questions',$occ['question_id']);$doc=CAFCC_Academic::get('documents',$occ['document_id']);$ed=CAFCC_Academic::get('editions',$occ['edition_id']);$sub=CAFCC_Repository::get('subjects',$ed['subject_id']);$tags=CAFCC_DB::table('question_tags');
        $d=array('stable_id'=>'EXISTING-O-'.$occid,'source_hash'=>$input['source_hash']??'','source_key'=>$doc['document_key'],'subject_code'=>$sub['code'],'source_type'=>$doc['source_type'],'exam_attempt'=>$doc['exam_attempt'],'mtp_series'=>$doc['mtp_series'],'section'=>$input['section']??'owner-identification-required','reference'=>$occ['question_number'],'subreference'=>$occ['subquestion_number'],'title'=>$doc['title'],'official_url'=>$doc['official_url'],'edition_id'=>$occ['edition_id'],'classification'=>array_map('intval',$wpdb->get_col($wpdb->prepare("SELECT node_id FROM $tags WHERE question_id=%d",$q['id']))));
        $d=self::clean($d);if(is_wp_error($d))return $d;$values=self::columns($d);$values=array_merge($values,array('question_id'=>$q['id'],'occurrence_id'=>$occid,'approvals'=>'{}','status'=>'needs_review','publication_status'=>'draft','batch_key'=>'existing-v03'));
        if(false===$wpdb->insert($t,$values))return CAFCC_Repository::error('Cannot prepare existing occurrence.',409);$r=self::get($wpdb->insert_id);return self::audit($r,'existing_v03_review')?$r:CAFCC_Repository::error('Cannot retain adoption history.',500);
    }
    public static function withdraw($key){
        if(is_wp_error($e=self::admin()))return $e;if(!is_string($key)||!preg_match('/^[A-Za-z0-9_.:-]{2,120}$/D',$key))return CAFCC_Repository::error('Invalid batch key.');global $wpdb;$t=self::table();$ids=$wpdb->get_col($wpdb->prepare("SELECT id FROM $t WHERE batch_key=%s",$key));foreach($ids as $id){$r=self::get($id);$v=self::decision($id,array('expected_revision'=>$r['revision'],'action'=>'hold','confirmed'=>true));if(is_wp_error($v))return $v;}return array('withdrawn'=>count($ids),'retained'=>'All IDs, source evidence, approvals history and student records.');
    }
    public static function routes(){
        $admin=function($r){return CAFCC_REST::permission($r,true);};
        register_rest_route('cafcc/v4','/admin/reviews',array('methods'=>'GET','permission_callback'=>$admin,'callback'=>array(__CLASS__,'listing')));
        register_rest_route('cafcc/v4','/admin/reviews/(?P<id>[1-9][0-9]{0,17})',array(array('methods'=>'GET','permission_callback'=>$admin,'callback'=>function($r){return self::get((int)$r['id'])?:CAFCC_Repository::error('Not found.',404);}),array('methods'=>'PATCH','permission_callback'=>$admin,'callback'=>function($r){$d=self::body($r);return is_wp_error($d)?$d:self::save((int)$r['id'],$d);})));
        register_rest_route('cafcc/v4','/admin/reviews/(?P<id>[1-9][0-9]{0,17})/decision',array('methods'=>'POST','permission_callback'=>$admin,'callback'=>function($r){$d=self::body($r);return is_wp_error($d)?$d:self::decision((int)$r['id'],$d);}));
        register_rest_route('cafcc/v4','/admin/reviews/(?P<id>[1-9][0-9]{0,17})/history',array('methods'=>'GET','permission_callback'=>$admin,'callback'=>function($r){global $wpdb;$t=CAFCC_Bank_DB::table('audit');return $wpdb->get_results($wpdb->prepare("SELECT * FROM $t WHERE review_id=%d ORDER BY id DESC LIMIT 100",$r['id']),ARRAY_A);}));
        register_rest_route('cafcc/v4','/admin/research/withdraw',array('methods'=>'POST','permission_callback'=>$admin,'callback'=>function($r){$d=self::body($r);return is_wp_error($d)?$d:self::withdraw($d['batch_key']??null);}));
        register_rest_route('cafcc/v4','/admin/reviews/adopt/(?P<id>[1-9][0-9]{0,17})',array('methods'=>'POST','permission_callback'=>$admin,'callback'=>function($r){$d=self::body($r);return is_wp_error($d)?$d:self::adopt((int)$r['id'],$d);}));
        register_rest_route('cafcc/v4','/admin/taxonomy-search',array('methods'=>'GET','permission_callback'=>$admin,'callback'=>function($r){global $wpdb;$term=$r->get_param('term')??'';$edition=$r->get_param('edition_id');if(!is_string($term)||strlen($term)>120)return CAFCC_Repository::error('Invalid search.');$t=CAFCC_DB::table('taxonomy');$args=array('%'.$wpdb->esc_like($term).'%');$where='title LIKE %s';if($edition){$id=CAFCC_Repository::id($edition);if(is_wp_error($id))return $id;$where.=' AND edition_id=%d';$args[]=$id;}return array('items'=>$wpdb->get_results($wpdb->prepare("SELECT id,title,node_type,edition_id,heading_origin,review_status FROM $t WHERE $where ORDER BY position,id LIMIT 50",$args),ARRAY_A),'editions'=>CAFCC_Academic::listing('editions')['items']);}));
        foreach(array('preview','apply') as $action)register_rest_route('cafcc/v4','/admin/research/'.$action,array('methods'=>'POST','permission_callback'=>$admin,'callback'=>function($r)use($action){$d=self::body($r);return is_wp_error($d)?$d:('preview'===$action?self::import_preview($d):self::import_apply($d['token']??null));}));
    }
    public static function screen(){if(is_wp_error(self::admin()))wp_die('Administrator access required.');echo '<div class="wrap cafcc-studio" id="cafcc-studio"><header><span>ACADEMIC OPERATIONS · PRIVATE</span><h1>Question Review Studio</h1><p>Inspect the evidence. Approve each stage. Publish only when eligible.</p></header><div class="studio-toolbar"><input type="search" id="studio-search" placeholder="Search ID, concept, attempt or evidence" aria-label="Search reviews"><select id="studio-status" aria-label="Review status"><option value="">All statuses</option><option>needs_review</option><option>hold</option><option>rejected</option><option>approved</option></select><select id="studio-sort" aria-label="Sort column"><option value="id">Newest record</option><option value="subject_code">Subject</option><option value="exam_attempt">Attempt</option><option value="modified_at">Modified</option></select><button id="studio-export" type="button">Download Review Excel</button><label>Upload decisions<input type="file" id="studio-excel" accept=".xlsx"></label><label>Import research batch<input type="file" id="studio-import" accept=".json"></label></div><details><summary>Visible columns</summary><div id="studio-columns"></div></details><p id="studio-feedback" role="status" aria-live="polite"></p><div class="studio-scroll" tabindex="0" aria-label="Review table; scroll horizontally"><table><thead id="studio-head"></thead><tbody id="studio-rows"></tbody></table></div><nav id="studio-pages" aria-label="Review pages"></nav><dialog id="studio-panel" aria-label="Review question"><div id="studio-detail"></div></dialog><section id="studio-upload-preview" hidden></section></div>';}
